import { z } from "zod";

/**
 * Validation for the door.
 *
 * A scanner is a camera pointed at arbitrary printed squares, so this is the one
 * endpoint where the payload genuinely cannot be trusted at all: it may be a
 * WiFi password, a bus ticket, or half a code read through a cracked screen.
 * Everything is bounded, trimmed and shape-checked before it reaches the
 * database.
 */

/** A UUID as generated by `crypto.randomUUID()` for each scan (idempotency key). */
const scanUuidSchema = z.uuid("Each scan needs its own scan id.");

/**
 * The code that was scanned, or typed.
 *
 * Three shapes are accepted, all of which the UI can produce:
 *   • `clubhub:ticket:<uuid>`  — exactly what the QR contains
 *   • `<uuid>`                 — copied from a ticket page
 *   • `A1B2C3D4`               — the 8-character door code, typed by hand
 *
 * The bounds are generous enough for the full payload and tight enough that a
 * megabyte of nonsense never reaches a query.
 */
const codeSchema = z
  .string()
  .trim()
  .min(4, "That code is too short to be a ticket.")
  .max(120, "That is not a ticket code.");

const scannedAtSchema = z
  .string()
  .datetime({ offset: true, message: "scannedAt must be an ISO timestamp." })
  .optional();

/** One scan: either taken live, or queued offline and synced later. */
export const checkInSchema = z.strictObject({
  code: codeSchema,
  source: z.enum(["SCANNER", "MANUAL"]).default("SCANNER"),
  /** Present on queued scans; absent for a live one, where the id is generated. */
  scanUuid: scanUuidSchema.optional(),
  /** When the scan happened. Offline queues can be hours old. */
  scannedAt: scannedAtSchema,
  deviceLabel: z.string().trim().max(60).optional(),
});

/**
 * The offline queue, flushed in one request.
 *
 * Bounded at 200: a door that has been offline all evening should sync in a
 * handful of batches rather than one enormous request the phone may drop.
 */
export const checkInBatchSchema = z.strictObject({
  scans: z
    .array(
      z.strictObject({
        scanUuid: scanUuidSchema,
        code: codeSchema,
        // Queued scans are recorded under the time they actually happened.
        scannedAt: z.string().datetime({ offset: true }).optional(),
        source: z.enum(["SCANNER", "MANUAL"]).default("SCANNER"),
      }),
    )
    .min(1, "There is nothing to sync.")
    .max(200, "Sync at most 200 scans at a time."),
  deviceLabel: z.string().trim().max(60).optional(),
});

export type CheckInInput = z.infer<typeof checkInSchema>;
export type CheckInBatchInput = z.infer<typeof checkInBatchSchema>;
